/**
 * This browser's endpoint key (MA-03 "endpoint keys", AP-20): one Ed25519 key per browser profile, generated by
 * `@whombat/secure-channel` with WebCrypto as **non-extractable** and kept in IndexedDB (the `CryptoKeyPair` is
 * stored by structured clone: script can sign with it but can never read the private key out). Qualified in
 * Chromium, Firefox and WebKit across reloads (contracts secure-channel ADR). Nothing here implements
 * cryptography.
 *
 * Every page that gets a key is a secure one (the box serves no page over plain HTTP, docs/decisions/direct-connection.md):
 * a page without WebCrypto gets no key at all, never a weaker one. A browser may still hold a software key (one script
 * can read) that an older box's plain-HTTP page made; it is never used, and the person forgets this browser to start
 * again (`weakKey`).
 */
import { fingerprintOf, formatFingerprint, sameFingerprint } from '@whombat/client/managed';
import {
  deserializeIdentity,
  generateWebCryptoIdentity,
  type Identity,
  identityFromCryptoKeyPair,
} from '@whombat/secure-channel';

const DB = 'whombat-keys';
const STORE = 'endpoint';
const KEY = 'default';
const KEY_CHANNEL = 'whombat:endpoint-key-deleted';

export interface EndpointKey {
  identity: Identity;
  /** A software key an older box's plain-HTTP page made: readable by script on this origin, never used. */
  software?: boolean;
  peerId: string;
  /** Short fingerprint for people to compare (groups of five). */
  fingerprint: string;
  createdAt: string;
}

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function tx<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return open().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const t = db.transaction(STORE, mode);
        let req: IDBRequest<T>;
        try {
          req = run(t.objectStore(STORE));
        } catch (error) {
          db.close();
          reject(error);
          return;
        }
        t.oncomplete = () => {
          db.close();
          resolve(req.result);
        };
        t.onabort = t.onerror = () => {
          db.close();
          reject(t.error);
        };
      }),
  );
}

export { fingerprintOf, formatFingerprint, sameFingerprint };

/** What IndexedDB holds: a WebCrypto key pair (structured clone), or an older software key's bytes. */
type Stored = { keyPair: CryptoKeyPair; createdAt: string } | { software: Uint8Array; createdAt: string };

async function describe(stored: Stored): Promise<EndpointKey> {
  const identity =
    'software' in stored
      ? deserializeIdentity(stored.software)
      : await identityFromCryptoKeyPair(stored.keyPair);
  const key = {
    peerId: identity.peerId,
    fingerprint: fingerprintOf(identity.peerId),
    createdAt: stored.createdAt,
    ...('software' in stored && { software: true }),
  } as EndpointKey;
  // Not enumerable: whatever walks an object's properties (React's development render logging diffs props this
  // way) never reaches the identity, whose `raw` getter throws for a non-exportable key and took the page down
  // (rc 0.5.2 device run).
  Object.defineProperty(key, 'identity', { value: identity, enumerable: false });
  return key;
}

/**
 * `slot`: which key — the browser's own (`default`), or the one it uses as a screen (`screen`, desk-display-web.md
 * AP-5960): a screen is its own endpoint, so the same browser can be a person's device and a screen.
 */
export async function loadEndpointKey(slot: string = KEY): Promise<EndpointKey | null> {
  const stored = await tx<Stored | undefined>('readonly', (s) => s.get(slot));
  return stored ? describe(stored) : null;
}

/** Whether this browser can keep a non-extractable Ed25519 key (Chromium, Firefox, Safari 17+) in IndexedDB. */
export async function endpointKeysSupportedCheck(): Promise<boolean> {
  if (typeof indexedDB === 'undefined' || !globalThis.crypto?.subtle) return false;
  try {
    await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
    return true;
  } catch {
    return false;
  }
}

/** How a page keeps its key: non-extractable in WebCrypto, or not at all. */
export type EndpointKeyStore = 'webcrypto' | 'unavailable';

/** Where this page's key can live: WebCrypto wherever it exists; a page without it gets none, never a weaker key. */
export function endpointKeyStore(page: { subtle: boolean }): EndpointKeyStore {
  return page.subtle ? 'webcrypto' : 'unavailable';
}

function thisPage() {
  return { subtle: !!globalThis.crypto?.subtle };
}

/**
 * Why this page has no key to use:
 * - `unsupported`: the browser can't keep one here (no WebCrypto Ed25519; `COPY.connection.unsupported`);
 * - `weakKey`: it holds a software key from before, which this page mustn't use. The person forgets this browser
 *   here and sets it up again with a key script can't read (`COPY.connection.weakKey`); nothing replaces it for them.
 */
export type EndpointKeyUnavailableReason = 'unsupported' | 'weakKey';

export class EndpointKeyUnavailableError extends Error {
  constructor(readonly reason: EndpointKeyUnavailableReason = 'unsupported') {
    super(`endpoint key unavailable on this page: ${reason}`);
    this.name = 'EndpointKeyUnavailableError';
  }
}

/**
 * The key, created on first use: non-extractable in WebCrypto. A stored software key from an older box's plain-HTTP
 * page is refused (`weakKey`), and a browser that can't use WebCrypto Ed25519 here gets `unsupported`, never a blank
 * page. `page` is for tests.
 */
export async function loadOrCreateEndpointKey(
  options: { slot?: string; page?: { subtle: boolean } } = {},
): Promise<EndpointKey> {
  const slot = options.slot ?? KEY;
  const store = endpointKeyStore(options.page ?? thisPage());
  const found = await tx<Stored | undefined>('readonly', (s) => s.get(slot));
  if (found) {
    if ('software' in found) throw new EndpointKeyUnavailableError('weakKey');
    if (store !== 'webcrypto') throw new EndpointKeyUnavailableError('unsupported');
    try {
      return await describe(found);
    } catch {
      throw new EndpointKeyUnavailableError('unsupported');
    }
  }
  if (store === 'unavailable') throw new EndpointKeyUnavailableError('unsupported');
  const createdAt = new Date().toISOString();
  let stored: Stored;
  // WebCrypto without Ed25519 (an older Safari on the box's Tailscale page) throws here.
  try {
    stored = { keyPair: (await generateWebCryptoIdentity({ extractable: false })).keyPair, createdAt };
  } catch {
    throw new EndpointKeyUnavailableError('unsupported');
  }
  // Several tabs may reopen together after sign-out. The transaction keeps their new identity the same.
  const selected = await tx<Stored | undefined>('readwrite', (s) => {
    const req = s.get(slot);
    req.onsuccess = () => {
      if (!req.result) s.put(stored, slot);
    };
    return req;
  });
  return describe(selected ?? stored);
}

/** “Forget this browser”: the key goes; every appliance will treat this browser as new. */
export async function deleteEndpointKey(slot: string = KEY): Promise<void> {
  await tx('readwrite', (s) => s.delete(slot));
  // Other tabs may still hold the deleted key and an open authenticated session in memory.
  try {
    const channel = new BroadcastChannel(KEY_CHANNEL);
    channel.postMessage(slot);
    channel.close();
  } catch {
    // Storage deletion still signs out this tab when this browser cannot open a broadcast channel.
  }
}

/** Close sessions in other tabs when this origin forgets their endpoint key. */
export function watchEndpointKeyDeletion(onDeleted: () => void, slot: string = KEY): () => void {
  try {
    const channel = new BroadcastChannel(KEY_CHANNEL);
    channel.onmessage = (event) => {
      if (event.data === slot) onDeleted();
    };
    return () => channel.close();
  } catch {
    return () => {};
  }
}

/** Label of this endpoint on the appliance (“Chrome on Linux”). */
export function browserLabel(ua: string = navigator.userAgent): string {
  const browser = /Edg\//.test(ua)
    ? 'Edge'
    : /Firefox\//.test(ua)
      ? 'Firefox'
      : /Chrome\//.test(ua)
        ? 'Chrome'
        : /Safari\//.test(ua)
          ? 'Safari'
          : 'Browser';
  const os = /Android/.test(ua)
    ? 'Android'
    : /iPhone|iPad/.test(ua)
      ? 'iOS'
      : /Mac OS X/.test(ua)
        ? 'Mac'
        : /Windows/.test(ua)
          ? 'Windows'
          : /Linux/.test(ua)
            ? 'Linux'
            : 'this computer';
  return `${browser} on ${os}`;
}
